// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockERC20 sglp;
    MockERC20 usdc;
    MockRewardRouter router;
    MockGlpManager glpManager;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e24);

        sglp = new MockERC20();
        usdc = new MockERC20();
        router = new MockRewardRouter();
        glpManager = new MockGlpManager();
        MockVault vault = new MockVault();
        address juniorVault = address(new JuniorVaultStub());

        c.initialize(
            IERC20(address(sglp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(router)),
            IGlpManager(address(glpManager)),
            juniorVault,
            address(this)
        );

        // keeper deposits `amount` worth of GLP into c on behalf of the junior vault
        vm.prank(juniorVault);
        c.depositToken(address(usdc), amount, 0);
        require(c.dnGmxJuniorVaultGlpBalance() == amount, "setup failed");

        // first batch deposit (cooldown satisfied: lastUnpauseTimestamp == 0)
        vm.warp(1000);
        c.executeBatchDeposit();
        // second batch deposit after the cooldown
        vm.warp(1000 + 901);
        c.executeBatchDeposit();

        // GENERAL RULE: the total sGlp c has ever transferred out to the junior
        // vault can never exceed the total GLP amount it received from deposits.
        assertTrue(sglp.sent() <= amount);
    }
}

